import csv
import json
from collections import defaultdict

# This script adds emails to games.json!

# YOU need to make an export from Attend, with
# Legal First Name,Legal Last Name,Email selected
# And rename the file to participants.csv
CSV_FILE = "participants.csv"

# games.json is generated by scrape.mjs
GAMES_FILE = "games.json"

# output with participant's emails
OUTPUT_FILE = "saturated.json"


def build_lookup(csv_path):
    lookup = defaultdict(list)

    with open(csv_path, mode="r", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        for row in reader:
            first_name = row["Legal First Name"].strip()
            last_name = row["Legal Last Name"].strip()
            email = row["Email"].strip()

            if not first_name or not last_name:
                continue

            short_name = f"{first_name} {last_name[0]}."
            full_name = f"{first_name} {last_name}"

            lookup[short_name.lower()].append({"name": full_name, "email": email})

    return lookup


def resolve_collision(member_str, matches, game):
    print("\n" + "=" * 60)
    print(f"Conflict at '{member_str}'")
    print(f"  Game:       {game.get('gameName', 'Unknown')}")
    print(f"  GitHub URL: {game.get('githubUrl', 'N/A')}")
    print(f"  Game URL:   {game.get('gameUrl', 'N/A')}")
    print(f"  Full Team:  {', '.join(game.get('teamMembers', []))}")
    print("-" * 60)

    for idx, person in enumerate(matches, start=1):
        print(f"  [{idx}] {person['name']}  <{person['email']}>")
    print("  [0] Keep original string (skip / email = null)")
    print("-" * 60)

    while True:
        choice = input(f"Select an option (0-{len(matches)}): ").strip()
        if choice.isdigit():
            num = int(choice)
            if num == 0:
                print(f"-> Kept '{member_str}' with null email.\n")
                return {"name": member_str, "email": None}
            if 1 <= num <= len(matches):
                selected = matches[num - 1]
                print(f"-> Selected: {selected['name']} <{selected['email']}>\n")
                return selected
        print(f"Invalid input. Please enter a number between 0 and {len(matches)}.")


def update_games(games_path, lookup, output_path):
    with open(games_path, mode="r", encoding="utf-8") as f:
        games = json.load(f)

    unmatched_log = []

    for game in games:
        updated_members = []
        for member_str in game.get("teamMembers", []):
            key = member_str.strip().lower()
            matches = lookup.get(key, [])

            if len(matches) == 1:
                updated_members.append(matches[0])
            elif len(matches) > 1:
                selected_person = resolve_collision(member_str, matches, game)
                updated_members.append(selected_person)
            else:
                unmatched_log.append((game.get("gameName", "Unknown"), member_str))
                updated_members.append({"name": member_str, "email": None})

        game["teamMembers"] = updated_members

    with open(output_path, mode="w", encoding="utf-8") as f:
        json.dump(games, f, indent=2, ensure_ascii=False)

    print("\n" + "=" * 60)
    print(f"Done! Saved updated JSON to '{output_path}'.")

    if unmatched_log:
        print(f"\nUnmatched entries ({len(unmatched_log)} total, saved with email: null):")
        for game_name, member in unmatched_log:
            print(f"  - '{member}' in '{game_name}'")


if __name__ == "__main__":
    member_lookup = build_lookup(CSV_FILE)
    update_games(GAMES_FILE, member_lookup, OUTPUT_FILE)